use vstd::prelude::*;

verus! {
    /// Transpose a non‐empty, rectangular matrix of f32's.
    ///
    /// Input `x` has `row_count = x.len() ≥ 1` rows, each of length 
    /// `col_count = x[0].len() ≥ 1`, and all rows have the same length.
    ///
    /// We produce `result` of size `col_count × row_count` such that
    /// for all i < col_count, j < row_count,
    ///     result[i][j] == x[j][i].
    fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> (result: Vec<Vec<f32>>)
        requires
            // At least one row…
            x.len() > 0,
            // …and at least one column
            x[0].len() > 0,
            // All rows have the same length
            forall(|r: usize| r < x.len() ==> x[r].len() == x[0].len()),
        ensures
            // The transpose has `col_count` rows…
            result.len() == x[0].len(),
            // …and each output row has length = original row count
            forall(|i: usize| i < result.len() ==> result[i].len() == x.len()),
            // And the element‐wise transpose condition
            forall(|i: usize, j: usize|
                i < result.len() && j < result[i].len() ==>
                result[i][j] == x[j][i]),
    {
        let row_count = x.len();
        let col_count = x[0].len();

        // We'll build up `result` row by row (each row has length = row_count).
        let mut result: Vec<Vec<f32>> = Vec::with_capacity(col_count);
        let mut c: usize = 0;
        while c < col_count
            invariant
                // we've done `c` rows so far
                c <= col_count,
                result.len() == c,
                // each of the first `c` rows has length `row_count`
                forall(|i: usize| i < c ==> result[i].len() == row_count),
                // and up to now we've satisfied the transpose property
                forall(|i: usize, j: usize|
                    i < c && j < row_count ==>
                    result[i][j] == x[j][i]),
            decreases col_count - c,
        {
            // build the `c`-th row of the transpose
            let mut new_row: Vec<f32> = Vec::with_capacity(row_count);
            let mut r: usize = 0;
            while r < row_count
                invariant
                    r <= row_count,
                    new_row.len() == r,
                    // new_row[j] == x[j][c] for j < r
                    forall(|j: usize| j < r ==> new_row[j] == x[j][c]),
                decreases row_count - r,
            {
                new_row.push(x[r][c]);
                r += 1;
            }
            // after the inner loop, new_row.len() == row_count
            // and new_row[j] == x[j][c] for all j < row_count
            assert(forall(|j: usize| j < row_count ==> new_row[j] == x[j][c]));

            result.push(new_row);
            c += 1;
        }

        result
    }
}

